#define GPU_MARKER ".Hogs-GPU-HD-Profile.txt"
#define GPU_BACKUP_PREFIX ".Hogs-GPU-HD-backup-"
#define GPU_MAX_FILES 64
#define GPU_PATH_CAP 2048
#define GPU_HASH_CAP 65
#define GPU_CONFIG "[TextureToolkit]\r\nResourceRoot=TT\r\nEnableInjection=1\r\nFinalRGBAReadback=1\r\nAutoDump=0\r\nVerbose=0\r\nFilterSmallTextures=0\r\nHighlightSelected=0\r\n"

typedef struct { char rel[512]; int existed; char old_hash[65]; char new_hash[65]; } StateFile;
typedef struct { char backup[128]; int tt_existed, inject_existed; size_t count; StateFile files[GPU_MAX_FILES]; } ProfileState;
static void msg(char *out,size_t cap,const char *s){if(cap)snprintf(out,cap,"%s",s);}
static int safe_rel(const char *s){if(!s||!*s||s[0]=='/'||s[0]=='\\'||strchr(s,':'))return 0;const char*p=s;while(*p){const char*q=strpbrk(p,"/\\");size_t n=q?(size_t)(q-p):strlen(p);if(!n||(n==1&&p[0]=='.')||(n==2&&p[0]=='.'&&p[1]=='.'))return 0;if(!q)break;p=q+1;}return 1;}
static wchar_t *wide(const char *s){int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,NULL,0);if(!n)return NULL;wchar_t*w=HeapAlloc(GetProcessHeap(),0,(SIZE_T)n*sizeof(*w));if(w&&!MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s,-1,w,n)){HeapFree(GetProcessHeap(),0,w);return NULL;}return w;}
static int path_join(char *out,size_t cap,const char *root,const char *rel){int n=snprintf(out,cap,"%s\\%s",root,rel);return n>0&&(size_t)n<cap;}
static int attr(const char *path,DWORD *a){wchar_t*w=wide(path);if(!w)return -1;DWORD x=GetFileAttributesW(w);DWORD e=GetLastError();HeapFree(GetProcessHeap(),0,w);if(x==INVALID_FILE_ATTRIBUTES){if(e==ERROR_FILE_NOT_FOUND||e==ERROR_PATH_NOT_FOUND)return 0;return -1;}if(x&FILE_ATTRIBUTE_REPARSE_POINT)return -1;if(a)*a=x;return 1;}
static int make_dir(const char *path){wchar_t*w=wide(path);if(!w)return 0;BOOL r=CreateDirectoryW(w,NULL);DWORD e=GetLastError();HeapFree(GetProcessHeap(),0,w);return r||e==ERROR_ALREADY_EXISTS;}
static int remove_dir(const char *path){wchar_t*w=wide(path);if(!w)return 0;BOOL r=RemoveDirectoryW(w);DWORD e=GetLastError();HeapFree(GetProcessHeap(),0,w);return r||e==ERROR_PATH_NOT_FOUND||e==ERROR_FILE_NOT_FOUND;}
static int hash_open(HANDLE f,unsigned char out[32]){BCRYPT_ALG_HANDLE alg=NULL;BCRYPT_HASH_HANDLE hash=NULL;DWORD objlen=0,got=0;PUCHAR obj=NULL;unsigned char buf[65536];int ok=BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,NULL,0)>=0;if(ok)ok=BCryptGetProperty(alg,BCRYPT_OBJECT_LENGTH,(PUCHAR)&objlen,sizeof(objlen),&got,0)>=0;if(ok)obj=HeapAlloc(GetProcessHeap(),0,objlen);if(ok&&!obj)ok=0;if(ok)ok=BCryptCreateHash(alg,&hash,obj,objlen,NULL,0,0)>=0;while(ok){DWORD n=0;if(!ReadFile(f,buf,sizeof(buf),&n,NULL)){ok=0;break;}if(!n)break;if(BCryptHashData(hash,buf,n,0)<0)ok=0;}if(ok)ok=BCryptFinishHash(hash,out,32,0)>=0;if(hash)BCryptDestroyHash(hash);if(obj)HeapFree(GetProcessHeap(),0,obj);if(alg)BCryptCloseAlgorithmProvider(alg,0);return ok;}
static int hash_file(const char *path,char hex[65]){wchar_t*w=wide(path);if(!w)return 0;HANDLE f=CreateFileW(w,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);HeapFree(GetProcessHeap(),0,w);if(f==INVALID_HANDLE_VALUE)return 0;unsigned char h[32];int ok=hash_open(f,h);CloseHandle(f);if(!ok)return 0;static const char d[]="0123456789abcdef";for(int i=0;i<32;i++){hex[i*2]=d[h[i]>>4];hex[i*2+1]=d[h[i]&15];}hex[64]=0;return 1;}
static int valid_hash(const char*s){if(!s||strlen(s)!=64)return 0;for(int i=0;i<64;i++)if(!((s[i]>='0'&&s[i]<='9')||(s[i]>='a'&&s[i]<='f')))return 0;return 1;}
static int write_atomic(const char *path,const void *data,size_t n){wchar_t*dst=wide(path);if(!dst)return 0;size_t cap=wcslen(dst)+64;wchar_t*tmp=HeapAlloc(GetProcessHeap(),0,cap*sizeof(*tmp));if(!tmp){HeapFree(GetProcessHeap(),0,dst);return 0;}HANDLE f=INVALID_HANDLE_VALUE;for(int i=0;i<32;i++){_snwprintf(tmp,cap,L"%ls.hogs-gpu-%08lx-%02x",dst,(unsigned long)GetCurrentProcessId(),(unsigned)i);f=CreateFileW(tmp,GENERIC_WRITE,0,NULL,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,NULL);if(f!=INVALID_HANDLE_VALUE)break;if(GetLastError()!=ERROR_FILE_EXISTS&&GetLastError()!=ERROR_ALREADY_EXISTS)break;}size_t at=0;int ok=f!=INVALID_HANDLE_VALUE;while(ok&&at<n){DWORD want=(DWORD)((n-at)>0x40000000u?0x40000000u:n-at),wrote=0;if(!WriteFile(f,(const unsigned char*)data+at,want,&wrote,NULL)||!wrote)ok=0;else at+=wrote;}if(ok)ok=FlushFileBuffers(f);if(f!=INVALID_HANDLE_VALUE)CloseHandle(f);if(ok)ok=MoveFileExW(tmp,dst,MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)!=0;if(!ok)DeleteFileW(tmp);HeapFree(GetProcessHeap(),0,tmp);HeapFree(GetProcessHeap(),0,dst);return ok;}
static int copy_file(const char *src,const char *dst,BOOL no_overwrite){wchar_t*a=wide(src),*b=wide(dst);if(!a||!b){if(a)HeapFree(GetProcessHeap(),0,a);if(b)HeapFree(GetProcessHeap(),0,b);return 0;}BOOL ok=CopyFileW(a,b,no_overwrite);HeapFree(GetProcessHeap(),0,a);HeapFree(GetProcessHeap(),0,b);return ok;}
static int delete_file(const char *path){wchar_t*w=wide(path);if(!w)return 0;BOOL ok=DeleteFileW(w);DWORD e=GetLastError();HeapFree(GetProcessHeap(),0,w);return ok||e==ERROR_FILE_NOT_FOUND||e==ERROR_PATH_NOT_FOUND;}
static int create_parent_dirs(const char *game,const char *rel){char p[GPU_PATH_CAP];if(!path_join(p,sizeof(p),game,rel))return 0;if(!strchr(rel,'\\')&&!strchr(rel,'/'))return 1;char*slash=strrchr(p,'\\');if(!slash)return 0;*slash=0;char*slash2=strrchr(p,'\\');if(!slash2)return 0;*slash2=0;DWORD a;int ex=attr(p,&a);if(ex==1)return (a&FILE_ATTRIBUTE_DIRECTORY)!=0;if(ex<0)return 0;if(!make_dir(p))return 0;*slash2='\\';slash=strrchr(p,'\\');if(!slash)return 0;*slash=0;ex=attr(p,&a);if(ex==1)return (a&FILE_ATTRIBUTE_DIRECTORY)!=0;if(ex<0)return 0;return make_dir(p);}
static int hash_mem(const unsigned char *p,size_t n,char out[65]){BCRYPT_ALG_HANDLE alg=NULL;BCRYPT_HASH_HANDLE hash=NULL;DWORD z=0,got=0;PUCHAR obj=NULL;unsigned char h[32];int ok=BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,NULL,0)>=0;if(ok)ok=BCryptGetProperty(alg,BCRYPT_OBJECT_LENGTH,(PUCHAR)&z,sizeof(z),&got,0)>=0;if(ok)obj=HeapAlloc(GetProcessHeap(),0,z);if(ok&&!obj)ok=0;if(ok)ok=BCryptCreateHash(alg,&hash,obj,z,NULL,0,0)>=0;if(ok&&n)ok=BCryptHashData(hash,(PUCHAR)p,(ULONG)n,0)>=0;if(ok)ok=BCryptFinishHash(hash,h,32,0)>=0;if(hash)BCryptDestroyHash(hash);if(obj)HeapFree(GetProcessHeap(),0,obj);if(alg)BCryptCloseAlgorithmProvider(alg,0);if(!ok)return 0;static const char d[]="0123456789abcdef";for(int i=0;i<32;i++){out[i*2]=d[h[i]>>4];out[i*2+1]=d[h[i]&15];}out[64]=0;return 1;}

int hogs_archive_guard_check(const char *game,const unsigned char *guard,size_t guard_len,char *message,size_t cap){if(!guard||guard_len<10||guard_len>65536||memcmp(guard,"HOGSORG1\n",9)){msg(message,cap,"Контрольный список игровых файлов повреждён. Ничего не менял.");return 0;}size_t pos=9;unsigned count=0;while(pos<guard_len){size_t end=pos;while(end<guard_len&&guard[end]!='\n')end++;size_t n=end-pos;if(n&&guard[pos+n-1]=='\r')n--;if(!n){pos=end+1;continue;}if(n>=600){msg(message,cap,"Запись списка игровых файлов повреждена.");return 0;}char line[600];memcpy(line,guard+pos,n);line[n]=0;char*tab=strchr(line,'\t');if(!tab){msg(message,cap,"Запись списка игровых файлов повреждена.");return 0;}*tab++=0;if(!safe_rel(line)||!valid_hash(tab)){msg(message,cap,"Запись списка игровых файлов повреждена.");return 0;}char path[GPU_PATH_CAP],actual[65];if(!path_join(path,sizeof(path),game,line)||!hash_file(path,actual)){msg(message,cap,"Не удалось проверить игровые архивы. Ничего не менял.");return 0;}if(strcmp(actual,tab)){msg(message,cap,"В выбранной папке изменены игровые архивы. Восстанови исходные файлы через Steam и повтори попытку.");return 0;}count++;pos=end<guard_len?end+1:end;}if(count!=140){msg(message,cap,"В контрольном списке должно быть 140 игровых архивов. Ничего не менял.");return 0;}msg(message,cap,"Исходные игровые архивы проверены.");return 1;}

static int state_write(const char *game,const ProfileState*s){char marker[GPU_PATH_CAP],buf[32768];if(!path_join(marker,sizeof(marker),game,GPU_MARKER))return 0;int n=snprintf(buf,sizeof(buf),"HOGSGPU1\n%s\n%d\n%d\n%u\n",s->backup,s->tt_existed,s->inject_existed,(unsigned)s->count);if(n<0||(size_t)n>=sizeof(buf))return 0;size_t at=(size_t)n;for(size_t i=0;i<s->count;i++){const StateFile*f=&s->files[i];n=snprintf(buf+at,sizeof(buf)-at,"%s\t%d\t%s\t%s\n",f->rel,f->existed,f->existed?f->old_hash:"-",f->new_hash);if(n<0||(size_t)n>=sizeof(buf)-at)return 0;at+=(size_t)n;}return write_atomic(marker,buf,at);}
static int allowed_profile_path(const char *p){
    static const char *fixed[]={"TextureToolkit.ini","DDraw.dll","D3DImm.dll","dgVoodoo.conf","TextureToolkit-x86.asi","LICENSE-TextureToolkit.txt","DgVoodoo-Redistribution.txt"};
    for(size_t i=0;i<sizeof(fixed)/sizeof(fixed[0]);i++)if(!_stricmp(p,fixed[i]))return 1;
    const char *prefix="TT\\inject\\";size_t n=strlen(prefix);if(_strnicmp(p,prefix,n))return 0;p+=n;
    if(strlen(p)!=20||_stricmp(p+16,".dds"))return 0;
    for(int i=0;i<16;i++)if(!((p[i]>='0'&&p[i]<='9')||(p[i]>='A'&&p[i]<='F')))return 0;
    return 1;
}
static int profile_payload_preflight(const HogsProfileFile*files,size_t count,char*message,size_t cap){
    static const char *required[]={"DDraw.dll","D3DImm.dll","dgVoodoo.conf","TextureToolkit-x86.asi","LICENSE-TextureToolkit.txt","DgVoodoo-Redistribution.txt"};
    int found[6]={0,0,0,0,0,0};unsigned pages=0;size_t total=0;
    if(!files||count!=30){msg(message,cap,"HD-пакет не содержит ожидаемые 24 страницы и 6 компонентов.");return 0;}
    for(size_t i=0;i<count;i++){
        const HogsProfileFile*f=&files[i];char actual[65];
        if(!f->relative_path||!f->data||!f->size||!safe_rel(f->relative_path)||!allowed_profile_path(f->relative_path)||!strcmp(f->relative_path,"TextureToolkit.ini")){msg(message,cap,"В HD-пакете найден некорректный файл.");return 0;}
        if(f->size>16u*1024u*1024u||total>64u*1024u*1024u-f->size){msg(message,cap,"Размер HD-пакета превышает допустимый.");return 0;}total+=f->size;
        if(!hash_mem(f->data,f->size,actual)||(f->sha256&&strcmp(actual,f->sha256))){msg(message,cap,"HD-пакет повреждён. Файлы игры не менялись.");return 0;}
        const char *page_prefix="TT\\inject\\";size_t page_prefix_len=strlen(page_prefix);
        if(!_strnicmp(f->relative_path,page_prefix,page_prefix_len))pages++;
        else {int matched=0;for(int j=0;j<6;j++)if(!_stricmp(f->relative_path,required[j])){if(found[j]){msg(message,cap,"В HD-пакете повторяется файл.");return 0;}found[j]=1;matched=1;break;}if(!matched){msg(message,cap,"В HD-пакете неизвестный файл.");return 0;}}
        for(size_t j=0;j<i;j++)if(!_stricmp(files[j].relative_path,f->relative_path)){msg(message,cap,"В HD-пакете повторяется файл.");return 0;}
    }
    if(pages!=24){msg(message,cap,"В HD-пакете должно быть 24 текстурные страницы.");return 0;}
    for(int i=0;i<6;i++)if(!found[i]){msg(message,cap,"В HD-пакете отсутствует обязательный компонент.");return 0;}
    return 1;
}
static int state_read(const char*game,ProfileState*s){char marker[GPU_PATH_CAP],line[1200];if(!path_join(marker,sizeof(marker),game,GPU_MARKER))return 0;wchar_t*w=wide(marker);if(!w)return 0;FILE*f=_wfopen(w,L"rb");HeapFree(GetProcessHeap(),0,w);if(!f)return 0;memset(s,0,sizeof(*s));int ok=fgets(line,sizeof(line),f)&&!strcmp(line,"HOGSGPU1\n")&&fgets(line,sizeof(line),f);if(ok){line[strcspn(line,"\r\n")]=0;if(strncmp(line,GPU_BACKUP_PREFIX,strlen(GPU_BACKUP_PREFIX))||strstr(line,"..")||strchr(line,'\\')||strlen(line)>=sizeof(s->backup))ok=0;else strcpy(s->backup,line);}if(ok&&fgets(line,sizeof(line),f)){s->tt_existed=atoi(line);ok=s->tt_existed==0||s->tt_existed==1;}else ok=0;if(ok&&fgets(line,sizeof(line),f)){s->inject_existed=atoi(line);ok=s->inject_existed==0||s->inject_existed==1;}else ok=0;if(ok&&fgets(line,sizeof(line),f)){unsigned n=0;ok=sscanf(line,"%u",&n)==1&&n>0&&n<=GPU_MAX_FILES;s->count=n;ok=ok&&n==31;}else ok=0;for(size_t i=0;ok&&i<s->count;i++){if(!fgets(line,sizeof(line),f)){ok=0;break;}line[strcspn(line,"\r\n")]=0;char*a=strchr(line,'\t');if(!a){ok=0;break;}*a++=0;char*b=strchr(a,'\t');if(!b){ok=0;break;}*b++=0;char*c=strchr(b,'\t');if(!c){ok=0;break;}*c++=0;if(!safe_rel(line)||strlen(line)>=sizeof(s->files[i].rel)||!allowed_profile_path(line)){ok=0;break;}for(size_t j=0;j<i;j++)if(!_stricmp(s->files[j].rel,line)){ok=0;break;}if(!ok)break;StateFile*r=&s->files[i];strcpy(r->rel,line);r->existed=atoi(a);if(r->existed!=0&&r->existed!=1){ok=0;break;}if(r->existed){if(!valid_hash(b)){ok=0;break;}strcpy(r->old_hash,b);}else if(strcmp(b,"-")){ok=0;break;}if(!valid_hash(c)){ok=0;break;}strcpy(r->new_hash,c);}if(ok&&fgets(line,sizeof(line),f))ok=0;fclose(f);return ok;}
static int ensure_dir2(const char*path,int*existed){DWORD a;int e=attr(path,&a);if(e<0)return 0;*existed=e==1;if(e==1)return (a&FILE_ATTRIBUTE_DIRECTORY)!=0;return make_dir(path);}
static int state_file_path(const char*game,const char*backup,const char*rel,char*out){char b[GPU_PATH_CAP];if(!path_join(b,sizeof(b),game,backup))return 0;return path_join(out,GPU_PATH_CAP,b,rel);}

int hogs_gpu_profile_install(const char *game,const unsigned char *guard,size_t guard_len,const HogsProfileFile *files,size_t file_count,char *message,size_t cap){if(!profile_payload_preflight(files,file_count,message,cap))return 0;if(!hogs_archive_guard_check(game,guard,guard_len,message,cap))return 0;char marker[GPU_PATH_CAP];if(!path_join(marker,sizeof(marker),game,GPU_MARKER))return 0;DWORD ma;int marker_exists=attr(marker,&ma);if(marker_exists!=0){msg(message,cap,marker_exists>0?"HD-профиль уже записан. Для изменения сначала восстанови прежний профиль.":"Не удалось проверить установку HD-профиля.");return 0;}
    ProfileState s;memset(&s,0,sizeof(s));char tt[GPU_PATH_CAP],inject[GPU_PATH_CAP],backuproot[GPU_PATH_CAP];if(!path_join(tt,sizeof(tt),game,"TT")||!path_join(inject,sizeof(inject),game,"TT\\inject"))return 0;int tt_ex=0,inj_ex=0;if(!ensure_dir2(tt,&tt_ex)){msg(message,cap,"Не удалось подготовить папку текстур. Ничего не менял.");return 0;}if(!ensure_dir2(inject,&inj_ex)){if(!tt_ex)remove_dir(tt);msg(message,cap,"Не удалось подготовить папку текстур. Ничего не менял.");return 0;}s.tt_existed=tt_ex;s.inject_existed=inj_ex;
    WIN32_FIND_DATAW fd;
    wchar_t*winject=wide(inject);if(!winject){msg(message,cap,"Не удалось проверить папку текстур.");return 0;}size_t wn=wcslen(winject);wchar_t*search=HeapAlloc(GetProcessHeap(),0,(wn+4)*sizeof(wchar_t));if(!search){HeapFree(GetProcessHeap(),0,winject);return 0;}swprintf(search,wn+4,L"%ls\\*",winject);HANDLE find=FindFirstFileW(search,&fd);int any=0;if(find!=INVALID_HANDLE_VALUE){do{if(wcscmp(fd.cFileName,L".")&&wcscmp(fd.cFileName,L"..")){any=1;break;}}while(FindNextFileW(find,&fd));FindClose(find);}HeapFree(GetProcessHeap(),0,search);HeapFree(GetProcessHeap(),0,winject);if(any){msg(message,cap,"Папка TT\\inject уже содержит файлы. Убери их или сохрани отдельно и повтори.");if(!inj_ex)remove_dir(inject);if(!tt_ex)remove_dir(tt);return 0;}
    SYSTEMTIME st;GetLocalTime(&st);int made=0;for(unsigned k=0;k<100;k++){snprintf(s.backup,sizeof(s.backup),GPU_BACKUP_PREFIX "%04u%02u%02u-%02u%02u%02u-%02u",st.wYear,st.wMonth,st.wDay,st.wHour,st.wMinute,st.wSecond,k);if(!path_join(backuproot,sizeof(backuproot),game,s.backup))break;wchar_t*wb=wide(backuproot);if(!wb)break;BOOL ok=CreateDirectoryW(wb,NULL);DWORD err=GetLastError();HeapFree(GetProcessHeap(),0,wb);if(ok){made=1;break;}if(err!=ERROR_ALREADY_EXISTS)break;}if(!made){msg(message,cap,"Не удалось создать резервную копию.");if(!inj_ex)remove_dir(inject);if(!tt_ex)remove_dir(tt);return 0;}
    char config[]=GPU_CONFIG;size_t nfiles=file_count+1;if(nfiles>GPU_MAX_FILES){msg(message,cap,"В HD-профиле слишком много файлов.");return 0;}s.count=nfiles;
    HogsProfileFile config_file={"TextureToolkit.ini",(const unsigned char*)config,sizeof(config)-1,NULL};
    for(size_t i=0;i<nfiles;i++){const HogsProfileFile*f=i<file_count?&files[i]:&config_file;StateFile*r=&s.files[i];if(!safe_rel(f->relative_path)||strlen(f->relative_path)>=sizeof(r->rel)){msg(message,cap,"В HD-пакете найден некорректный путь.");return 0;}strcpy(r->rel,f->relative_path);char target[GPU_PATH_CAP];if(!path_join(target,sizeof(target),game,r->rel)){msg(message,cap,"Путь к HD-файлу слишком длинный.");return 0;}DWORD a;int ex=attr(target,&a);if(ex<0||(ex==1&&(a&FILE_ATTRIBUTE_DIRECTORY))){msg(message,cap,"В папке игры есть файл или ссылка, которую нельзя безопасно заменить.");return 0;}r->existed=ex==1;if(r->existed&&!hash_file(target,r->old_hash)){msg(message,cap,"Не удалось сохранить прежний файл. Ничего не менял.");return 0;}if(!hash_mem(f->data,f->size,r->new_hash)||(f->sha256&&strcmp(r->new_hash,f->sha256))){msg(message,cap,"HD-пакет повреждён. Файлы игры не менялись.");return 0;}}
    for(size_t i=0;i<s.count;i++)if(s.files[i].existed){char orig[GPU_PATH_CAP],dst[GPU_PATH_CAP],leaf[64];snprintf(leaf,sizeof(leaf),"old-%02u.bin",(unsigned)i);char backrel[128];snprintf(backrel,sizeof(backrel),"%s",leaf);if(!state_file_path(game,s.backup,backrel,dst)||!path_join(orig,sizeof(orig),game,s.files[i].rel)||!copy_file(orig,dst,TRUE)){msg(message,cap,"Не удалось создать полную резервную копию. Ничего не устанавливал.");return 0;}}
    if(!state_write(game,&s)){msg(message,cap,"Не удалось записать данные для отката. Файлы игры не менялись.");return 0;}
    int ok=1;for(size_t i=0;i<s.count&&ok;i++){const HogsProfileFile*f=i<file_count?&files[i]:&config_file;char target[GPU_PATH_CAP];if(!path_join(target,sizeof(target),game,s.files[i].rel)||!create_parent_dirs(game,s.files[i].rel)||!write_atomic(target,f->data,f->size))ok=0;else{char h[65];if(!hash_file(target,h)||strcmp(h,s.files[i].new_hash))ok=0;}}
    if(!ok){msg(message,cap,"Не удалось завершить установку. Запись для безопасного отката сохранена; повтори восстановление.");return 0;}msg(message,cap,"24 страницы HD-профиля готовы. Перезапусти игру, чтобы проверить их.");return 1;}

int hogs_gpu_profile_restore(const char*game,const HogsProfileFile*files,size_t file_count,char*message,size_t cap){(void)files;(void)file_count;ProfileState s;if(!state_read(game,&s)){msg(message,cap,"Для этой папки не найдена корректная запись HD-профиля.");return 0;}char backuproot[GPU_PATH_CAP];if(!path_join(backuproot,sizeof(backuproot),game,s.backup)){msg(message,cap,"Резервная копия не найдена.");return 0;}for(size_t i=0;i<s.count;i++){char cur[GPU_PATH_CAP],now[65];if(!path_join(cur,sizeof(cur),game,s.files[i].rel)){msg(message,cap,"Путь файла повреждён.");return 0;}int exists=attr(cur,NULL);if(s.files[i].existed){if(exists!=1||!hash_file(cur,now)||(strcmp(now,s.files[i].new_hash)&&strcmp(now,s.files[i].old_hash))){msg(message,cap,"Файл HD-профиля изменён. Ничего не восстановил.");return 0;}char leaf[64],backup[GPU_PATH_CAP];snprintf(leaf,sizeof(leaf),"old-%02u.bin",(unsigned)i);if(!path_join(backup,sizeof(backup),backuproot,leaf)||!hash_file(backup,now)||strcmp(now,s.files[i].old_hash)){msg(message,cap,"Резервная копия повреждена. Ничего не восстановил.");return 0;}}else if(exists==1&&(!hash_file(cur,now)||strcmp(now,s.files[i].new_hash))){msg(message,cap,"Файл HD-профиля изменён. Ничего не восстановил.");return 0;}else if(exists<0){msg(message,cap,"Не удалось проверить файлы HD-профиля.");return 0;}}
    for(size_t i=0;i<s.count;i++){char cur[GPU_PATH_CAP],backup[GPU_PATH_CAP],leaf[64];path_join(cur,sizeof(cur),game,s.files[i].rel);if(s.files[i].existed){snprintf(leaf,sizeof(leaf),"old-%02u.bin",(unsigned)i);path_join(backup,sizeof(backup),backuproot,leaf);if(!copy_file(backup,cur,FALSE)){msg(message,cap,"Не удалось вернуть прежний файл. Резервная копия сохранена.");return 0;}}else if(!delete_file(cur)){msg(message,cap,"Не удалось убрать файл профиля. Резервная копия сохранена.");return 0;}}
    char marker[GPU_PATH_CAP];path_join(marker,sizeof(marker),game,GPU_MARKER);delete_file(marker);char tt[GPU_PATH_CAP],inject[GPU_PATH_CAP];path_join(tt,sizeof(tt),game,"TT");path_join(inject,sizeof(inject),game,"TT\\inject");if(!s.inject_existed)remove_dir(inject);if(!s.tt_existed)remove_dir(tt);msg(message,cap,"HD-профиль отключён. Резервная копия оставлена в папке игры.");return 1;}
